    if len(s) == 0:
        return 0

    # Find the longest common prefix and suffix
    common_prefix = s[0]
    common_suffix = s[-1]

    # Check if the entire string is the same as both the prefix and suffix
    if s == common_prefix * len(s):
        return len(s)

    # If not, find the length of the common prefix and suffix
    for i in range(len(common_prefix)):
        if common_prefix[i] != common_suffix[len(common_suffix) - 1 - i]:
