def min_max_normalize(nums: list[float]) -> list[float]:
    if len(nums) == 0:
        return []

    min_val = min(nums)
    max_val = max(nums)

    if min_val == max_val:
        return [1] * len(nums)

    normalized_nums = [(num - min_val) / (max_val - min_val) for num in nums]

    return normalized_nums
