from collections import deque

def height_queue_reconstruction(people: list[list[int]]) -> list[list[int]]:
    people.sort(key=lambda x: (-x[0], -x[1]))
    queue = deque()

    for h, k in people:
        while queue and queue[-1][0] >= h:
            queue.pop()
        queue.append([h, k])

    return queue

