def is_valid_parentheses(s: str) -> bool:
    stack = []

    for char in s:
        if char == '(' or char == '[' or char == '{':
            stack.append(char)
        elif char == ')' and (not stack or stack.pop() != '('):
            return False
        elif char == ']' and (not stack or stack.pop() != '['):
            return False
        elif char == '}' and (not stack or stack.pop() != '{'):
            return False

    return len(stack) == 0
