def boustrophedon_order(matrix: list[list[int]]) -> list[int]:
    if not matrix:
        return []

    result = []
    rows, cols = len(matrix), len(matrix[0])
    top, bottom, left, right = 0, rows - 1, 0, cols - 1

    while top <= bottom and left <= right:
        # Traverse from left to right in the current column
        for i in range(left, right + 1):
            result.append(matrix[top][i])
        top += 1

        # Traverse from top to bottom in the current row
        for i in range(top, bottom + 1):
            result.append(matrix[i][right])
        right -= 1

        # Check if there is another column to traverse
        if top <= bottom:
            # Traverse from right to left in the current column
            for i in range(right, left - 1, -1):
                result.append(matrix[bottom][i])
            bottom -= 1

        # Check if there is another row to traverse
        if left <= right:
            # Traverse from bottom to top in the current row
            for i in range(bottom, top - 1, -1):
                result.append(matrix[i][left])
            left += 1

    return result
