import math

def token_entropy(tokens: list[str]) -> float:
    if not tokens:
        return 0.0

    total_tokens = len(tokens)
    frequency_dict = {}

    for token in tokens:
        if token in frequency_dict:
            frequency_dict[token] += 1
        else:
            frequency_dict[token] = 1

    entropy = 0.0
    for count in frequency_dict.values():
        probability = count / total_tokens
        entropy -= probability * math.log2(probability)

    return entropy
