def balanced_ternary_str(n: int) -> str:
    if n == 0:
        return "0"

    result = ""
    while n != 0:
        remainder = n % 3
        if remainder == 2:
            result = "-" + result
            n -= 6
        else:
            result = str(remainder) + result
            n //= 3

    return result
