def balanced_ternary_str(n: int) -> str:
    if n == 0:
        return '0'

    result = []
    while n != 0:
        remainder = n % 3
        result.append(str(remainder))
        n //= 3

    # Reverse the list to get the correct order
    result.reverse()

    # Replace '-' with '+' for negative numbers
    for i in range(len(result)):
        if result[i] == '-':
            result[i] = '+'

    return ''.join(result)
