from typing import List

def moving_average(nums: List[float], window: int) -> List[float]:
    if window <= 0 or len(nums) < window:
        return []

    result = []
    for i in range(len(nums) - window + 1):
        avg = sum(nums[i:i+window]) / window
        rounded_avg = round(avg, 2)
        result.append(rounded_avg)

    return result

