    if not matrix:
        return []

    result = []
    rows = len(matrix)
    cols = len(matrix[0])
    i, j = 0, 0

    while i < rows and j < cols:
        # Add elements from the top-left to bottom-right diagonal
        for k in range(cols):
            result.append(matrix[i][k])
            i += 1

        # If we have reached the end of the current column, move to the next row
        if i == rows:
            break

        # Add elements from the bottom-right to top-left diagonal
        for k in range(rows - 1, -1, -1):
            result.append(matrix[k][j])
            j += 1

        # If we have reached the end of the current row, move to the previous column
        if j == cols:
            break

    return result

