def boustrophedon_order(matrix: list[list[int]]) -> list[int]:
    if not matrix:
        return []

    result = []
    row, col = len(matrix), len(matrix[0])
    directions = [(1, 0), (-1, 0), (0, 1), (0, -1)]
    visited = [[False] * col for _ in range(row)]

    def dfs(i, j):
        if i < 0 or i >= row or j < 0 or j >= col or visited[i][j]:
            return
        result.append(matrix[i][j])
        visited[i][j] = True

        for dx, dy in directions:
            dfs(i + dx, j + dy)

    # Start from any cell
    for i in range(row):
        for j in range(col):
            if not visited[i][j]:
                dfs(i, j)
                break

    return result
