def balanced_ternary_str(n: int) -> str:
    if n == 0:
        return "0"

    digits = []
    while n != 0:
        remainder = n % 3
        digits.append(str(remainder))
        n //= 3

    # Reverse the list to get the correct order and remove leading zeros
    digits.reverse()
    while digits and digits[-1] == '0':
        digits.pop()

    # Join the digits into a string
    return ''.join(digits)
