import hashlib

def derive_key(passphrase: str, salt: bytes) -> bytes:
    # Ensure the passphrase is non-empty and contains non-ASCII characters
    if not passphrase or not all(ord(c) < 128 for c in passphrase):
        raise ValueError("Passphrase must be non-empty and contain only ASCII characters")

    # Ensure the salt is at least 8 bytes long
    if len(salt) < 8:
        raise ValueError("Salt must be at least 8 bytes long")

    # Derive the key using SHA-512 hashing
    return hashlib.sha512((passphrase.encode('utf-8') + salt).digest()).digest()[:32]

