            '(': lambda x, y: [x, y],
            ')': lambda x, y: y
        }

        # Initialize stack for parentheses
        stack = []

        i = 0
        while i < len(expression):
            if expression[i] == '(':
                stack.append(i)
            elif expression[i] == ')':
                start = stack.pop()
                sub_expr = expression[start + 1:i]
                result = evaluate_expression(sub_expr)
