def evaluate_expression(expression: str) -> float:
    if not expression or '(' in expression or ')' in expression:
        raise ValueError("Invalid expression")

    # Replace spaces with nothing to simplify parsing
    expression = expression.replace(' ', '')

    # Define a helper function for parsing and evaluating expressions
    def parse_and_evaluate(tokens):
        stack = []
        for token in tokens:
            if token.isdigit():
                stack.append(float(token))
            elif token == '(':
                stack.append(token)
            elif token == ')':
                while stack[-1] != '(':
                    right = stack.pop()
                    left = stack.pop()
                    if token == '+':
                        stack.append(left + right)
                    elif token == '-':
                        stack.append(left - right)
                    elif token == '*':
                        stack.append(left * right)
                    elif token == '/':
