                if token == '-' and len(stack) > 0 and isinstance(stack[-1], (int, float)):
                    stack[-1] = -stack[-1]
                else:
                    raise ValueError(f"Invalid token: {token}")

        if len(stack) != 1:
            raise ValueError("Invalid expression")

        return stack[0]

