def evaluate_expression(expression: str) -> float:
    if not expression.strip():
        raise ValueError("Expression cannot be empty")

    # Remove spaces from the expression
    expression = expression.replace(" ", "")

    # Define the regular expression for matching tokens
    token_pattern = r"[-+]?\d+(\.\d+)?|[\+\-\*/\(\)]"

    # Find all tokens in the expression
    tokens = re.findall(token_pattern, expression)

    # Initialize the stack for operators
    operator_stack = []

    # Initialize the result
    result = 0

    # Iterate over each token
    for token in tokens:
        if token.isdigit() or '.' in token:
            # Convert the token to a float and push it onto the result stack
            result += float(token)
        elif token == '(':
            # Push the current result onto the operator stack and reset the result
            operator_stack.append(result)
            result = 0
        elif token == ')':
            # Pop the last result from the operator stack and apply the corresponding operator
            prev_result = operator_stack.pop()
            if operator_stack:
                operator = operator_stack.pop()
                if operator == '+':
