import re

def evaluate_expression(expression: str) -> float:
    if not expression.strip():
        raise ValueError("Expression cannot be empty")

    # Replace spaces with nothing to simplify parsing
    expression = expression.replace(" ", "")

    # Define a regular expression pattern for matching tokens
    token_pattern = r"(\d+(\.\d+)?)|[-+\*/]**|\(|\)|-"

    # Find all matches in the expression
    tokens = re.findall(token_pattern, expression)

    # Initialize the stack for operators and operands
    operator_stack = []
    operand_stack = []

    # Iterate over each token
    for token in tokens:
        if token.isdigit() or '.' in token:
            # Push numeric tokens onto the operand stack
            operand_stack.append(float(token))
        elif token == '(':
            # Push opening parenthesis onto the operator stack
            operator_stack.append(token)
        elif token == ')':
            # Pop operators from the stack until reaching the corresponding opening parenthesis
            while operator_stack[-1] != '(':
                op = operator_stack.pop()
                b = operand_stack.pop()
                a = operand_stack.pop()
                if op == '+':
                    operand_stack.append(a + b)
                elif op == '-':
                    operand_stack.append(a - b)
                elif op == '*':
                    operand_stack.append(a * b)
                elif op == '/':
                    if b == 0:
                        raise ZeroDivisionError("Division by zero")
                    operand_stack.append(a / b)
                elif op == '**':
                    operand_stack.append(a ** b)
            # Pop the opening parenthesis from the stack
            operator_stack.pop()
        else:
            # Handle unary minus
            if token == '-' and len(operand_stack) > 0:
                operand_stack.append(-operand_stack.pop())
            else:
                raise ValueError(f"Unknown token: {token}")

    # Evaluate the remaining operators on the operand stack
    while operator_stack:
        op = operator_stack.pop()
        b = operand_stack.pop()
        a = operand_stack.pop()
        if op == '+':
            operand_stack.append(a + b)
        elif op == '-':
            operand_stack.append(a - b)
        elif op == '*':
            operand_stack.append(a * b)
        elif op == '/':
            if b == 0:
                raise ZeroDivisionError("Division by zero")
            operand_stack.append(a / b)
        elif op == '**':
            operand_stack.append(a ** b)

    # The final result should be the only element left in the operand stack
    return operand_stack[0]
