            elif expression[i] == "(":
                tokens.append("(")
            elif expression[i] == ")":
                tokens.append(")")
            i += 1

        # Evaluate the expression using the Shunting Yard algorithm
        output_queue = []
        operator_stack = []

        for token in tokens:
            if isinstance(token, float):
