import re
from collections import deque

class InvalidExpressionError(ValueError):
    pass

class EvaluationError(ZeroDivisionError):
    pass

def evaluate_expression(expression: str) -> float:
    if not expression:
        raise ValueError("Invalid expression")

    # Remove spaces from the expression
    expression = expression.replace(" ", "")

    # Check for invalid characters
    if not re.match(r'^[+-]?(\d+(\.\d*)?|\.\d+)([+\-*/]**)?([+-]?\d+(\.\d*)?|\.\d+)?$', expression):
        raise ValueError("Invalid expression")

    # Define the precedence and associativity of operators
    precedence = {
        '+': 1,
        '-': 1,
        '*': 2,
        '/': 2,
        '**': 3
    }
    associativity = {
        '+': 'left',
        '-': 'left',
        '*': 'left',
        '/': 'left',
        '**': 'right'
    }

    # Split the expression into tokens
    tokens = []
    i = 0
    while i < len(expression):
        if expression[i].isdigit():
            num = ''
            while i < len(expression) and expression[i].isdigit():
                num += expression[i]
                i += 1
            tokens.append(float(num))
        elif expression[i] in "+-*/**":
            tokens.append(expression[i])
            i += 1
        elif expression[i] == '(':
            tokens.append('(')
            i += 1
        elif expression[i] == ')':
            tokens.append(')')
            i += 1
        else:
            raise ValueError("Invalid character")

    # Evaluate the expression using the Shunting Yard algorithm
    output_queue = deque()
    operator_stack = deque()

    for token in tokens:
        if isinstance(token, float):
            output_queue.append(token)
        elif token == '(':
            operator_stack.append(token)
        elif token == ')':
            while operator_stack[-1] != '(':
                output_queue.append(operator_stack.pop())
            operator_stack.pop()
        else:
            while operator_stack and (operator_stack[-1] != '(' and precedence[token] <= precedence[operator_stack[-1]] and associativity[token] == 'left'):
                output_queue.append(operator_stack.pop())
            operator_stack.append(token)

    while operator_stack:
        output_queue.append(operator_stack.pop())

    # Evaluate the postfix expression
    stack = deque()
    for token in output_queue:
        if isinstance(token, float):
            stack.append(token)
        else:
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)
            elif token == '/':
                if b == 0:
                    raise EvaluationError("Division by zero")
                stack.append(a / b)
            elif token == '**':
                stack.append(a ** b)

    if len(stack) != 1:
        raise ValueError("Invalid expression")

    return stack.pop()
