import re

def is_allowed_webhook(url: str) -> bool:
    # Check if URL starts with https://
    if not url.startswith("https://"):
        return False

    # Remove user info
    url = re.sub(r'(?<=:[^@]*)@', '', url)

    # Check for backslashes, spaces, and control characters
    if "\\" in url or " " in url or "\x00" <= url.encode()[0] < "\x20":
        return False

    # Split host and port
    parts = url.split(":")
    host = parts[0]
    port = parts[1] if len(parts) > 1 else None

    # Check DNS name format
    if "." in host:
        labels = host.split(".")
        if len(labels) < 2 or any(label == "" or not label.isalnum() or "-" in label for label in labels):
            return False
        if labels[-1].isdigit():
            return False
        if host.endswith(".localhost") or host.lower().endswith(".localhost"):
            return False
        if port is not None and int(port) != 443:
            return False
    else:
        return False

    return True
