    if not url.startswith('https://') or any(char in url for char in '!@#$%^&*()_+-=[]{}|\\:;"\'<>,.?/'):
        return False

    # Extract host from URL
    host = re.search(r'https?://([^/]+)', url).group(1)

    # Check if host contains invalid characters or special symbols
    if any(char in host for char in "!@#$%^&*()_+-=[]{}|\\:;"\'<>,.?/"):
        return False

    # Check if host is a valid DNS name
    if not re.match(r'^[a-zA-Z0-9.-]+\.[a-zA-Z]{2,}$', host):
        return False

    # Check if host is localhost or .localhost
    if host == "localhost" or host.endswith(".localhost"):
        return True

    # Check if port is 443
    if ":" in host:
        port = int(host.split(":")[1])
        if port != 443:
            return False

    return True

