    if not strs:
        return ""

    # Start with the first string as the initial prefix
    prefix = strs[0]

    for s in strs[1:]:
        while s.startswith(prefix) == False:
            # Reduce the prefix by one character from the end until it matches the start of the current string
            prefix = prefix[:-1]

            # If the prefix becomes empty, there's no common prefix
            if not prefix:
                return ""

    return prefix
