def roman_char_distance(w1: str, w2: str) -> int:
    def char_to_value(c):
        if c == 'I':
            return 1
        elif c == 'V':
            return 5
        elif c == 'X':
            return 10
        elif c == 'L':
            return 50
        elif c == 'C':
            return 100
        elif c == 'D':
            return 500
        elif c == 'M':
            return 1000
        else:
            raise ValueError("Invalid Roman numeral character")

    dist = 0
    i, j = 0, 0

    while i < len(w1) and j < len(w2):
        v1 = char_to_value(w1[i])
        v2 = char_to_value(w2[j])

        if v1 > v2:
            dist += v1 - v2
            i += 1
        elif v1 < v2:
            dist += v2 - v1
            j += 1
        else:
            dist += min(v1, v2)
            i += 1
            j += 1

    # Add the remaining characters from the longer string
    dist += max(len(w1) - i, len(w2) - j)

    return dist
