def compress_string(s: str) -> str:
    if not s:
        return ""

    compressed = []
    count = 1

    for i in range(1, len(s)):
        if s[i] == s[i - 1]:
            count += 1
        else:
            compressed.append(f"{count}{s[i - 1]}")
            count = 1

    # Append the last character and its count
    compressed.append(f"{count}{s[-1]}")

    # Join all characters in the list into a string
    compressed_str = ''.join(compressed)

    # Check if the compressed string is shorter than or equal to the original string
    if len(compressed_str) <= len(s):
        return s
    else:
        return compressed_str
