def balanced_ternary_str(n: int) -> str:
    if n == 0:
        return '0'

    result = []
    while n != 0:
        remainder = n % 3
        if remainder == -1:
            result.append('-')
            n += 2
        else:
            result.append(str(remainder))
            n -= remainder

        # Ensure the first non-zero digit appears at the beginning
        if len(result) > 1 and result[0] == '0':
            result.pop(0)

    return ''.join(reversed(result))
