            elif token == '(':
                stack.append(token)
            elif token == ')':
                while stack[-1] != '(':
                    right = stack.pop()
                    left = stack.pop()
                    stack.append(apply_operator(stack.pop(), left, right))
                stack.pop()

        while stack:
            right = stack.pop()
            left = stack.pop()
            stack.append(apply_operator(stack.pop(), left, right))

        return stack[0]

    try:
