def is_allowed_webhook(url: str) -> bool:
    # Check if the URL starts with "https://"
    if not url.lower().startswith("https://"):
        return False

    # Check for user information in the format "user@" or "user:password@"
    if "@" in url and ":" in url:
        return False

    # Check for special characters other than spaces and control characters (ASCII codes 32-127)
    if not re.match(r'^[a-zA-Z0-9\s\p{Cntrl}]*$', url):
        return False

    # Check if the URL ends with a period followed by one or more labels separated by dots
    if not re.match(r'.*\.\w+$', url):
        return False

    # Check if the URL is "localhost" or ".localhost"
    if url == "localhost" or url == ".localhost":
        return False

    # Check if the URL does not include a port number or uses the default HTTPS port of 443
    if ":" in url:
        return False

    return True
