import re

def is_allowed_webhook(url: str) -> bool:
    # Check if the URL starts with "https://"
    if not url.lower().startswith("https://"):
        return False

    # Split the URL into scheme, netloc, path, query, and fragment
    parts = url.split("/")

    # Check for user information before the '@' symbol
    if "@" in parts[0]:
        return False

    # Check for backslashes, spaces, or control characters
    if re.search(r"[\\s\p{C}]", parts[0]):
        return False

    # Check if the URL ends with a single dot followed by two or more labels
    if len(parts) < 2 or parts[-1] != "." or len(parts[-2]) == 0:
        return False

    # Check if the domain cannot be "localhost" or ".localhost"
    if parts[1].lower() in ["localhost", ".localhost"]:
        return False

    # Check if the port number is any integer except 443
    if ":" in parts[1]:
        try:
            port = int(parts[1].split(":")[1])
            if port == 443:
                return False
        except ValueError:
            return False

    # Simple text check to ensure the URL structure is correct
    if not re.match(r"^https?://[^@]+(\.[^@]+)+$", url):
        return False

    return True
