def group_by_mod(nums: list[int], m: int) -> dict[int, list[int]]:
    """
    Groups numbers in nums by their modulo with m.

    Args:
        nums: A list of integers.
        m: An integer divisor.

    Returns:
        A dictionary where keys are the remainders when numbers are divided by m,
        and values are lists of numbers that have the same remainder.

    If m is not an integer, returns an empty dictionary.
    """
    if not isinstance(m, int):
        return {}

    result = {}
    for num in nums:
        remainder = num % m
        if remainder in result:
            result[remainder].append(num)
        else:
            result[remainder] = [num]

    return result
