def balanced_ternary_str(n: int) -> str:
    if n == 0:
        return "0"

    digits = []
    while n != 0:
        remainder = n % 3
        digits.append(str(remainder))
        n //= 3

    digits.reverse()

    while len(digits) < 4:
        digits.insert(0, '0')

    return ''.join(digits)
