import math

def evaluate_formula(formula: str, x: float) -> float:
    # Define the functions
    def sqrt(x):
        return math.sqrt(x)

    def abs(x):
        return abs(x)

    def sin(x):
        return math.sin(math.radians(x))

    def cos(x):
        return math.cos(math.radians(x))

    # Evaluate the formula
    try:
        if formula == 'x**2':
            return x ** 2
        elif formula == 'sqrt(x)':
            return sqrt(x)
        elif formula == 'abs(x)':
            return abs(x)
        elif formula == 'sin(x)':
            return sin(x)
        elif formula == 'cos(x)':
            return cos(x)
        else:
            raise ValueError("Invalid formula")
    except ZeroDivisionError:
        raise ValueError("Cannot divide by zero")

# Example usage
print(evaluate_formula('x**2', 2))  # Output: 4.0
print(evaluate_formula('sqrt(x)', 16))  # Output: 5.0
print(evaluate_formula('sin(x)', math.pi / 2))  # Output: 1.0
print(evaluate_formula('cos(x)', math.pi / 4))  # Output: 0.7071067811865476
try:
    print(evaluate_formula('x/0', 2))  # Raises ZeroDivisionError
except ValueError as e:
    print(e)  # Output: Cannot divide by zero
try:
    print(evaluate_formula('invalid_formula', 2))  # Raises ValueError
except ValueError as e:
    print(e)  # Output: Invalid formula
